import React from "react";

export default function Register() {
  return (
    <div className="bg-[#292018] p-8 rounded-lg shadow-md w-[443px] inset-0 m-auto absolute h-[600px] border-[#F3B43F] border-4">
      <h1 className="font-bold mb-6 text-center font-imFeel text-[59px] bg-gradient-to-b from-[#F3B43F] to-[#8D6825] bg-clip-text text-transparent">
        REGISTRO
      </h1>
      <form>
        <div className="flex justify-center mb-4">
          <input
            type="text"
            id="user"
            className="w-[364px] px-3 py-2 text-black bg-[#DFC492] rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:bg-[#DFC492] font-imFeel text-[18px]"
            placeholder="Usuário"
          />
        </div>
        <div className="flex justify-center mb-4">
          <input
            type="password"
            id="password"
            className="w-[364px] px-3 py-2 text-black bg-[#DFC492] rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 font-imFeel text-[18px] focus:bg-[#DFC492]"
            placeholder="Senha"
          />
        </div>
        <div className="flex justify-center mb-4">
          <input
            type="password"
            id="confirm-password"
            className="w-[364px] px-3 py-2 text-black bg-[#DFC492] rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 font-imFeel text-[18px] focus:bg-[#DFC492]"
            placeholder="Confirmar Senha"
          />
        </div>
        <div className="flex justify-center mb-4">
          <input
            type="email"
            id="email"
            className="w-[364px] px-3 py-2 text-black bg-[#DFC492] rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 font-imFeel text-[18px] focus:bg-[#DFC492]"
            placeholder="E-mail"
          />
        </div>
        <div className="flex justify-center mb-4">
          <input
            type="email"
            id="confirm-email"
            className="w-[364px] px-3 py-2 text-black bg-[#DFC492] rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 font-imFeel text-[18px] focus:bg-[#DFC492]"
            placeholder="Confirmar E-mail"
          />
        </div>
        <div className="flex justify-center flex-wrap">
          <div className="flex items-center justify-center mb-4">
            <input
              className="mr-2 border-[#F3B43F] border-2 appearance-none w-5 h-5 rounded-sm checked:bg-yellow-500 checked:border-yellow-700 focus:outline-none"
              type="checkbox"
              name="remember"
              id="remember"
            />
            <label htmlFor="remember" className="font-imFeel text-1xl h-[19px]">
              Concordo com os{" "}
              <span className="text-blue-500 underline cursor-pointer hover:text-blue-400">
                Termos de Uso
              </span>
            </label>
          </div>
          <button className="w-[258px] h-[51px] bg-[#8D6825] font-imFeel text-white text-4xl mb-4 hover:bg-gradient-to-b rounded-2xl cursor-pointer hover:to-[#8D6825] hover:from-[#684424] border-[#F3B43F] border-4 items-center flex justify-center">
            REGISTRAR
          </button>
        </div>
      </form>
    </div>
  );
}
